# Названия стейтов и очков победы (этап 22). Запуск из папки mortaly_world: python ../tools/make_names.py
# Подбор по карте: coast/urban/hills/plains из definition.csv. Столицы: 210 Дворец власти, 242 Североград, 610 Мир.
import re
rows = {int(r.split(';')[0]): r.strip().split(';') for r in open('map/definition.csv', encoding='utf-8').readlines()[1:] if r.split(';')[0].isdigit()}
NORTH = list(range(169, 185)) + list(range(217, 265))
SOUTH = [n for n in range(169, 281) if n not in NORTH]
BLI = list(range(605, 621))
# теги: C берег, U город, H холмы, P равнина, '' любое
CRL_N = [('Дворец власти','U'),('Старый центр','U'),('Правительственный квартал','U'),('Стальной предел',''),('Суровск','U'),('Железный лог','H'),('Угольная слобода',''),('Литейск','U'),('Заводской район','U'),('Красный яр','H'),('Медный край','H'),('Дымный берег','C'),('Восточный вал','H'),('Гранитный мыс','C'),('Пепельная долина','P'),('Южный арсенал',''),('Тяжёлый порт','C'),('Военный посад','U'),('Нижние фабрики','U'),('Крепостной рубеж','H'),('Чёрный перевал','H'),('Плацдарм','C'),('Стальная гавань','C'),('Пограничье',''),
 ('Ржавый тракт',''),('Кузнечный лог','H'),('Свинцовая гряда','H'),('Коксовый посёлок','U'),('Бастионный хутор',''),('Угрюмый брод',''),('Чугунное поле','P'),('Шлаковый холм','H'),('Оружейная слобода','U'),('Штурмовой тракт',''),('Башенный мыс','C'),('Солёная бухта','C'),('Железный утёс','C'),('Казарменный городок','U'),('Мрачный бор','H'),('Горький берег','C'),('Гарнизонный посад','U'),('Серый карьер','H'),('Тёмный овраг','H'),('Каменный мост',''),('Закопчённый порт','C'),('Литейная гавань','C'),('Арсенальный тракт',''),('Чёрная гавань','C')]
PCL_N = [('Североград','U'),('Рассвет','U'),('Мирный рубеж','H'),('Сосновый край','H'),('Светлый берег','C'),('Верхняя долина','P'),('Новый путь',''),('Свободный мыс','C'),('Полевая слобода','P'),('Северные склады','U'),('Озёрный край','P'),('Зелёный тракт',''),
 ('Ясная гавань','C'),('Берёзовый лог','H'),('Тихая заводь','P'),('Утренний берег','C'),('Светлоярск','U'),('Добрый посад','U'),('Белая роща','H'),('Золотая нива','P'),('Весенняя долина','P'),('Хрустальный ручей','P'),('Северный причал','C'),('Заречье',''),('Липовая слобода','U'),('Лунная бухта','C'),('Солнечный косогор','H'),('Тополиный край','H'),('Ясные горы','H'),('Белый перевал','H'),('Мирная гавань','C'),('Ольховая заводь','P'),('Заповедный бор','H'),('Ромашковая степь','P'),('Серебряный ручей','P'),('Журавлиный берег','C'),('Новоград','U'),('Зелёная гряда','H'),('Рассветный порт','C'),('Ласковый берег','C'),('Согласие','U'),('Свободная слобода','U'),('Вольный край',''),('Ключевая долина','P'),('Кедровый бор','H'),('Тёплый берег','C'),('Речной посад','U'),('Васильковое поле','P'),('Дружный хутор',''),('Лесная опушка','H'),('Мирный брод',''),('Хлебный край','P'),('Каменная гряда','H'),('Тихий перевал','H'),('Приветливый мыс','C'),('Малиновый холм','H'),('Рябиновая роща','H'),('Парусный берег','C'),('Тихая пристань','C'),('Весенний тракт',''),('Новая слобода','U'),('Радужный мост',''),('Северные ворота','U'),('Зелёный холм','H')]
BLI_N = [('Мир','U'),('Лазурная гавань','U'),('Тихий мыс','P'),('Маячный остров','P'),('Бирюзовый риф','P'),('Северный атолл','P'),('Внешний берег','P'),('Малый Мир','U'),('Жемчужная бухта','U'),('Коралловый остров','P'),('Ветреный мыс','P'),('Рыбацкая слобода','U'),('Южный риф','P'),('Штормовой пролив','P'),('Парусный остров','U'),('Чайкин остров','P')]
FIX = {210: 'Дворец власти', 242: 'Североград', 610: 'Мир'}
def feat(n):
    r = rows[n]; return ('C' if r[5] == 'true' else '') + {'urban': 'U', 'hills': 'H', 'plains': 'P'}.get(r[6], '')
def assign(provs, names):
    assert len(names) >= len(provs), (len(names), len(provs))
    res = {}; used = set()
    for n, nm in FIX.items():
        if n in provs: res[n] = nm; used.add(nm)
    free = [n for n in provs if n not in res]
    pool = [(nm, tg) for nm, tg in names if nm not in used]
    # сначала прибрежные, потом городские, остальные
    def score(n, tg):
        f = feat(n); s = 0
        if tg == '': return 1
        if tg == 'C': return 5 if 'C' in f else -9
        if 'C' in f and tg != 'C': s -= 0
        return 4 if tg in f else -2
    cand = sorted(free, key=lambda n: (0 if 'C' in feat(n) else 1, n))
    for n in cand:
        best = max(pool, key=lambda p: score(n, p[1])); res[n] = best[0]; pool.remove(best)
    return res
names = {}
names.update(assign(SOUTH, CRL_N)); names.update(assign(NORTH, PCL_N)); names.update(assign(BLI, BLI_N))
assert len(names) == len(SOUTH) + len(NORTH) + len(BLI) and len(set(names.values())) == len(names)
for lang in ('russian', 'english'):
    p = f'localisation/{lang}/mortaly_world_l_{lang}.yml'; t = open(p, encoding='utf-8-sig').read(); c = 0
    for n, nm in names.items():
        t, k = re.subn(rf'^( (?:STATE|VICTORY_POINTS)_{n}:0 )".*"', rf'\1"{nm}"', t, flags=re.M); c += k
    open(p, 'w', encoding='utf-8-sig').write(t); print(lang, 'replaced', c)
bad = [(n, feat(n), nm) for n, nm in names.items() if ('C' in dict(CRL_N + PCL_N + BLI_N).get(nm, '')) and 'C' not in feat(n)]
print('прибрежные имена на неприбрежных:', bad)
